def nox(base, bank):
    n = "Датчик NOx (банк %d)" % bank
    block(base, n, "nox", "analog")
    code(hexcode(base, 5), n + ": подогрев, цепь", "nox", m="Цепь подогрева датчика NOx.")
    code(hexcode(base, 6), n + ": подогрев, низкий уровень", "nox", m="Цепь на массе.")
    code(hexcode(base, 7), n + ": подогрев, высокий уровень", "nox", m="Цепь оборвана.")
    code(hexcode(base, 8), n + ": контроль подогрева, цепь", "nox", m="Датчик не выходит на рабочую температуру.")
    code(hexcode(base, 9), n + ": контроль подогрева, вне диапазона", "nox", m="Температура датчика неправдоподобна.")
    code(hexcode(base, 10), n + ": контроль подогрева, низкий уровень", "nox", m="Цепь контроля на массе.")
    code(hexcode(base, 11), n + ": контроль подогрева, высокий уровень", "nox", m="Цепь контроля оборвана.")
    code(hexcode(base, 12), n + ": контроль подогрева, прерывистый", "nox", m="Сигнал пропадает.")

