def wide(bank, pos_base, ref_base, neg_base):
    n = "Широкополосный лямбда-зонд (банк %d, датчик 1)" % bank
    code(hexcode(pos_base), n + ": цепь тока накачки (+), обрыв", "afr", m="Обрыв в цепи положительного тока накачки: разъём, провод, датчик.")
    code(hexcode(pos_base, 1), n + ": ток накачки низкий", "afr", m="Ток накачки ниже нормы: цепь на массе, датчик.")
    code(hexcode(pos_base, 2), n + ": ток накачки высокий", "afr", m="Ток накачки выше нормы: замыкание на плюс, датчик.")
    code(hexcode(ref_base), n + ": опорное напряжение, обрыв", "afr", m="Обрыв цепи опорного напряжения датчика.")
    code(hexcode(ref_base, 1), n + ": опорное напряжение вне диапазона", "afr", m="Опорное напряжение неправдоподобно: датчик, разъём.")
    code(hexcode(ref_base, 2), n + ": опорное напряжение низкое", "afr", m="Цепь опоры на массе.")
    code(hexcode(ref_base, 3), n + ": опорное напряжение высокое", "afr", m="Цепь опоры на плюсе.")
    code(hexcode(neg_base), n + ": цепь тока накачки (−), обрыв", "afr", m="Обрыв в цепи отрицательного тока накачки.")
    code(hexcode(neg_base, 1), n + ": ток накачки (−) низкий", "afr", m="Цепь на массе.")
    code(hexcode(neg_base, 2), n + ": ток накачки (−) высокий", "afr", m="Цепь на плюсе.")

