for cyl in range(1, 13):
    base = 3401 + (cyl - 1) * 8
    for j, (what, fam) in enumerate([("впускных клапанов", "vvt_sol"), ("выпускных клапанов", "vvt_sol")]):
        b = base + j * 4
        code(hexcode(b), "Отключение цилиндра %d: управление %s, цепь / обрыв" % (cyl, what), fam, m="Обрыв в цепи соленоида отключения цилиндра.")
        code(hexcode(b, 1), "Отключение цилиндра %d: управление %s не отрабатывает" % (cyl, what), "vvt_perf", m="Соленоид работает, а клапаны не отключаются: давление масла, гидрокомпенсатор-отключатель.")
        code(hexcode(b, 2), "Отключение цилиндра %d: управление %s, низкий уровень" % (cyl, what), fam, m="Цепь на массе.")
        code(hexcode(b, 3), "Отключение цилиндра %d: управление %s, высокий уровень" % (cyl, what), fam, m="Цепь оборвана.")
